create trigger [trg_widget_summaries_insert] on [widget_summaries] instead of insert as
begin
    set nocount on;
insert into widgets (name) select n.name from inserted n;
end

create or replace function "trg_widget_summaries_insert_fn"() returns trigger language plpgsql as $$
begin
insert into widgets (name) select n.name from (select new."name" as "name") n;
    if tg_op = 'DELETE' then return old; end if;
    return new;
end
$$
